import json
import re
from docx import Document


def replace_placeholders_in_paragraph(paragraph, replacements):
    """Replace {{PLACEHOLDER}} patterns across runs, handling split-run cases."""
    # Build full text and a map from char index -> (run_index, char_index_in_run)
    full_text = ""
    char_map = []
    for ri, run in enumerate(paragraph.runs):
        for ci, ch in enumerate(run.text):
            char_map.append((ri, ci))
            full_text += ch

    if not full_text:
        return

    # Find all placeholders and process right-to-left
    matches = list(re.finditer(r'\{\{(\w+)\}\}', full_text))
    for match in reversed(matches):
        key = match.group(1)
        if key not in replacements:
            continue

        start, end = match.start(), match.end()
        replacement_value = replacements[key]

        start_run, start_pos = char_map[start]
        end_run, end_pos = char_map[end - 1]

        if start_run == end_run:
            run = paragraph.runs[start_run]
            run.text = run.text[:start_pos] + replacement_value + run.text[end_pos + 1:]
        else:
            first_run = paragraph.runs[start_run]
            last_run = paragraph.runs[end_run]

            first_run.text = first_run.text[:start_pos] + replacement_value
            last_run.text = last_run.text[end_pos + 1:]

            for ri in range(start_run + 1, end_run):
                paragraph.runs[ri].text = ""


def process_all_paragraphs(doc, replacements):
    """Process paragraphs in body and all tables (including nested)."""
    for paragraph in doc.paragraphs:
        replace_placeholders_in_paragraph(paragraph, replacements)

    def process_tables(tables):
        for table in tables:
            for row in table.rows:
                for cell in row.cells:
                    for paragraph in cell.paragraphs:
                        replace_placeholders_in_paragraph(paragraph, replacements)
                    process_tables(cell.tables)

    process_tables(doc.tables)


def remove_paragraph(paragraph):
    """Remove a paragraph element from the document XML."""
    p = paragraph._element
    p.getparent().remove(p)


# Load data
with open("/root/employee_data.json", "r") as f:
    data = json.load(f)

# Open template
doc = Document("/root/offer_letter_template.docx")

# Determine relocation condition
relocation = data.get("RELOCATION_PACKAGE", "No") == "Yes"

# Handle conditional section BEFORE placeholder replacement
if relocation:
    # Keep the content, just remove the IF/END_IF markers
    data["IF_RELOCATION"] = ""
    data["END_IF_RELOCATION"] = ""
else:
    # Remove the entire conditional paragraph(s)
    paragraphs_to_remove = []
    for paragraph in doc.paragraphs:
        if "{{IF_RELOCATION}}" in paragraph.text:
            paragraphs_to_remove.append(paragraph)
    for p in paragraphs_to_remove:
        remove_paragraph(p)

# Build replacements dict (exclude control fields)
skip_keys = {"RELOCATION_PACKAGE", "DOC_ID"}
replacements = {k: v for k, v in data.items() if k not in skip_keys}

# Process all paragraphs and tables
process_all_paragraphs(doc, replacements)

# Save
doc.save("/root/offer_letter_filled.docx")
print("Offer letter saved to /root/offer_letter_filled.docx")
